module tb_TopModule;
    logic [254:0] in;
    logic [7:0]   out;

    TopModule u_dut (
        .in(in),
        .out(out)
    );

    // Reference model function
    function [7:0] ref_popcount;
        input [254:0] val;
        integer k;
        begin
            ref_popcount = 0;
            for (k = 0; k < 255; k++) begin
                if (val[k]) ref_popcount = ref_popcount + 1;
            end
        end
    endfunction

    initial begin
        // Test case 1: All zeros
        in = 255'd0;
        #1;
        if (out !== ref_popcount(in)) begin
            $display("SELFTEST FAIL: All zeros. Expected %0d, got %0d", ref_popcount(in), out);
            $finish;
        end

        // Test case 2: All ones
        in = {255{1'b1}};
        #1;
        if (out !== ref_popcount(in)) begin
            $display("SELFTEST FAIL: All ones. Expected %0d, got %0d", ref_popcount(in), out);
            $finish;
        end

        // Test case 3: Alternating bits
        in = 255'h5555555555555555555555555555555555555555555555555555555555555555;
        #1;
        if (out !== ref_popcount(in)) begin
            $display("SELFTEST FAIL: Alternating 1. Expected %0d, got %0d", ref_popcount(in), out);
            $finish;
        end

        // Test case 4: Single bit set at various positions
        for (int i = 0; i < 255; i++) begin
            in = 255'd1 << i;
            #1;
            if (out !== ref_popcount(in)) begin
                $display("SELFTEST FAIL: Single bit at %0d. Expected %0d, got %0d", i, ref_popcount(in), out);
                $finish;
            end
        end

        // Test case 5: Pseudo-random patterns
        for (int t = 0; t < 100; t++) begin
            in = {$random, $random, $random, $random, $random, $random, $random, $random, $random};
            #1;
            if (out !== ref_popcount(in)) begin
                $display("SELFTEST FAIL: Random test %0d. Expected %0d, got %0d", t, ref_popcount(in), out);
                $finish;
            end
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
